(()=>{'use strict';
const SAVE_KEY='clash-cubs-save-v2';
const resourceInfo={honey:{name:'Honey',icon:'🍯'},berries:{name:'Berries',icon:'🫐'},fish:{name:'Fish',icon:'🐟'},toys:{name:'Toys',icon:'🧸'},wood:{name:'Timber',icon:'🪵'}};
const baseCaps={honey:250,berries:200,fish:150,toys:130,wood:260};
const catalog={
  nursery:{name:'Cub nursery',icon:'🛖',group:'Family',desc:'Raises how many cubs your den can train and take on adventures.',cost:{wood:55,honey:32},max:1},
  training:{name:'Training grove',icon:'🎯',group:'Family',desc:'Gives your squad more expedition spots.',cost:{wood:65,honey:25},max:1},
  hive:{name:'Honey hive',icon:'🍯',group:'Gathering',desc:'Produces honey every night.',cost:{wood:42,honey:20},resource:'honey',yield:28,max:4},
  berry:{name:'Berry patch',icon:'🫐',group:'Gathering',desc:'Grows a basket of berries every night.',cost:{wood:36,berries:12},resource:'berries',yield:22,max:4},
  pond:{name:'Fish pond',icon:'🐟',group:'Gathering',desc:'Fills your fish basket at the end of each day.',cost:{wood:44,berries:12},resource:'fish',yield:17,max:3},
  toyshop:{name:'Toy workshop',icon:'🧸',group:'Gathering',desc:'Makes a few new toys for the den each night.',cost:{wood:48,berries:18},resource:'toys',yield:15,max:3},
  mill:{name:'Timber mill',icon:'🪓',group:'Gathering',desc:'Turns fallen branches into building timber.',cost:{wood:38,honey:16},resource:'wood',yield:25,max:3},
  storage:{name:'Supply burrow',icon:'🧺',group:'Utility',desc:'Adds safe room for every kind of supply.',cost:{wood:62,honey:28},max:3},
  wall:{name:'Log wall',icon:'🪵',group:'Defense',desc:'Slows a rival raid and protects the stash.',cost:{wood:15},max:14},
  guard:{name:'Lookout post',icon:'🪺',group:'Defense',desc:'Adds a guard who helps turn away night visitors.',cost:{wood:46,honey:24},max:4},
  trap:{name:'Berry-basket decoy',icon:'🪤',group:'Defense',desc:'A harmless springy surprise that disrupts raiders.',cost:{wood:22,berries:13},max:5}
};
const units={
  roller:{name:'Roller cub',icon:'🛞',role:'Wall breaker',desc:'Crashes through log walls with a full-body tumble.',cost:{honey:20,berries:5},damage:27,hp:38,voice:'Wall first! I brought my whole self.'},
  climber:{name:'Climber cub',icon:'🧗',role:'Scout',desc:'Climbs over walls and slips past a guard to reach loot.',cost:{honey:18,berries:8},damage:18,hp:29,voice:'Look up! I found the shortcut!'},
  screecher:{name:'Screecher cub',icon:'📣',role:'Disruptor',desc:'Stuns the rival guard with one enormous holler.',cost:{honey:18,fish:8},damage:15,hp:32,voice:'Eeeee! That was my outside voice!'},
  tunnel:{name:'Tunnel cub',icon:'⛏️',role:'Burrower',desc:'Burrows under a wall and emerges beside a structure.',cost:{honey:22,wood:9},damage:21,hp:35,voice:'I made a surprise door!'},
  sleepy:{name:'Sleepy cub',icon:'😴',role:'Power move',desc:'Starts sluggish. Wake them before a big attack for a mighty bonk.',cost:{honey:13,fish:7},damage:9,hp:34,voice:'Five more minutes... wait, BONK!'}
};
const rivals=[
  {id:'maple',name:'Maple-Moon Outpost',mark:'🌙',difficulty:'Gentle scout',unlock:0,description:'A sunny little den with a sleepy lookout and a honey pantry.',targets:[
    {id:'wallA',name:'Brushwood wall',icon:'🧱',kind:'wall',hp:38,objective:false},
    {id:'guardA',name:'Fern lookout',icon:'🛡️',kind:'guard',hp:25,guard:true,objective:false},
    {id:'honeyA',name:'Honey nook',icon:'🍯',kind:'loot',hp:25,objective:true,loot:{honey:34}},
    {id:'berryA',name:'Berry basket',icon:'🫐',kind:'loot',hp:23,objective:true,loot:{berries:28}},
    {id:'homeA',name:'Mushroom pantry',icon:'🏠',kind:'home',hp:35,objective:true,loot:{wood:18}},
    {id:'toyA',name:'Toy shelf',icon:'🧸',kind:'loot',hp:24,objective:true,loot:{toys:19}}
  ]},
  {id:'cedar',name:'Cedar Stump Camp',mark:'🌲',difficulty:'A bit rowdier',unlock:1,description:'Two sturdy barriers guard the berry cellar and a busy toy shed.',targets:[
    {id:'wallB1',name:'Cedar barrier',icon:'🪵',kind:'wall',hp:48,objective:false},
    {id:'wallB2',name:'Root gate',icon:'🚪',kind:'wall',hp:42,objective:false},
    {id:'guardB',name:'Pine lookout',icon:'🛡️',kind:'guard',hp:30,guard:true,objective:false},
    {id:'berryB',name:'Berry cellar',icon:'🫐',kind:'loot',hp:30,objective:true,loot:{berries:42}},
    {id:'toyB',name:'Toy shed',icon:'🧸',kind:'loot',hp:31,objective:true,loot:{toys:35}},
    {id:'homeB',name:'Cedar den',icon:'🏠',kind:'home',hp:43,objective:true,loot:{wood:29,honey:16}}
  ]},
  {id:'river',name:'Riverstone Hollow',mark:'🪨',difficulty:'Careful planning',unlock:2,description:'Stone walls, a lively guard patrol, and a well-stocked fish store.',targets:[
    {id:'wallC1',name:'Riverstone wall',icon:'🪨',kind:'wall',hp:58,objective:false},
    {id:'guardC1',name:'North watch',icon:'🛡️',kind:'guard',hp:35,guard:true,objective:false},
    {id:'fishC',name:'Fish store',icon:'🐟',kind:'loot',hp:34,objective:true,loot:{fish:45}},
    {id:'honeyC',name:'Honey vault',icon:'🍯',kind:'loot',hp:37,objective:true,loot:{honey:48}},
    {id:'guardC2',name:'South watch',icon:'🪶',kind:'guard',hp:32,guard:true,objective:false},
    {id:'homeC',name:'Riverstone den',icon:'🏡',kind:'home',hp:55,objective:true,loot:{wood:38,toys:24}}
  ]}
];
const initial=()=>({day:1,wins:0,casualties:0,nextBuildId:40,resources:{honey:150,berries:92,fish:72,toys:42,wood:205},buildings:[
  {id:1,type:'home',x:3,y:2,level:1},{id:2,type:'nursery',x:2,y:2,level:1},{id:3,type:'training',x:4,y:2,level:1},{id:4,type:'storage',x:3,y:3,level:1},
  {id:5,type:'wall',x:2,y:1,level:1},{id:6,type:'wall',x:3,y:1,level:1},{id:7,type:'wall',x:4,y:1,level:1},{id:8,type:'wall',x:5,y:2,level:1},{id:9,type:'wall',x:4,y:3,level:1},{id:10,type:'wall',x:3,y:4,level:1},{id:11,type:'wall',x:2,y:3,level:1},{id:12,type:'wall',x:1,y:2,level:1},
  {id:13,type:'hive',x:0,y:0,level:1},{id:14,type:'berry',x:2,y:0,level:1},{id:15,type:'pond',x:5,y:0,level:1},{id:16,type:'toyshop',x:6,y:1,level:1},{id:17,type:'mill',x:0,y:4,level:1},
  {id:18,type:'guard',x:5,y:3,level:1},{id:19,type:'trap',x:1,y:4,level:1}
],roster:{roller:1,climber:1,screecher:0,tunnel:0,sleepy:1},squad:{roller:1,climber:1,screecher:0,tunnel:0,sleepy:1},collection:['roller','climber','sleepy'],history:[],activeRaid:null});
function loadState(){const base=initial();try{const raw=localStorage.getItem(SAVE_KEY);if(raw){const parsed=JSON.parse(raw);return {...base,...parsed,resources:{...base.resources,...parsed.resources},roster:{...base.roster,...parsed.roster},squad:{...base.squad,...parsed.squad}}}const legacy=JSON.parse(localStorage.getItem('clash-cubs-save')||'null');if(legacy){base.day=legacy.day||1;base.wins=legacy.wins||0;base.casualties=legacy.casualties||0;base.resources={...base.resources,...legacy.res};base.roster={...base.roster,...legacy.roster};base.collection=[...new Set([...base.collection,...(legacy.collection||[])])];for(const key of Object.keys(base.squad))base.squad[key]=Math.min(base.squad[key],base.roster[key]||0)}}catch{}return base}
let state=loadState();
if(countType('wall')<8){for(const [x,y] of [[3,1],[5,2],[4,3],[3,4],[2,3],[1,2],[5,3],[4,4]]){if(countType('wall')>=8)break;if(!state.buildings.some(b=>b.x===x&&b.y===y)){state.buildings.push({id:state.nextBuildId++,type:'wall',x,y,level:1})}}localStorage.setItem(SAVE_KEY,JSON.stringify(state))}
let page=state.activeRaid?'raid':'den',placement=null,selectedBuilding=null,selectedTroop=null,selectedTarget=null,toastTimer=null;
const save=()=>localStorage.setItem(SAVE_KEY,JSON.stringify(state));
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const total=(obj)=>Object.values(obj).reduce((a,b)=>a+(Number(b)||0),0);
const capFor=(r)=>baseCaps[r]+buildingLevel('storage')*150;
function countType(type){return state.buildings.filter(b=>b.type===type).length}
function findBuilding(id){return state.buildings.find(b=>b.id===Number(id))}
function buildingLevel(type){return state.buildings.filter(b=>b.type===type).reduce((n,b)=>n+b.level,0)}
function storageText(cost){return Object.entries(cost||{}).map(([r,n])=>`${resourceInfo[r].icon} ${n}`).join(' · ')||'Free'}
function canPay(cost){return Object.entries(cost).every(([r,n])=>(state.resources[r]||0)>=n)}
function pay(cost){if(!canPay(cost))return false;for(const [r,n] of Object.entries(cost))state.resources[r]-=n;return true}
function addSupply(r,n,container=state.resources){const before=container[r]||0,cap=capFor(r),next=Math.min(cap,before+n);container[r]=next;return n-(next-before)}
function toast(message){const root=document.querySelector('#toastroot');root.innerHTML=`<div class="toast">${esc(message)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>root.innerHTML='',2300)}
function addHistory(text){state.history.unshift({day:state.day,text});state.history=state.history.slice(0,12);save()}
function resourceHeader(){document.querySelector('#dayrail').textContent=state.day;document.querySelector('#resources').innerHTML=Object.entries(resourceInfo).map(([r,v])=>`<div class="resource" title="${esc(v.name)}"><span>${v.icon}</span><b>${state.resources[r]||0}<small> / ${capFor(r)}</small></b></div>`).join('')}
function showPage(next){page=next;placement=null;selectedTroop=null;selectedTarget=null;render()}
function render(){resourceHeader();const labels={den:'Your den',build:'Build den',train:'Cub nursery',raidMap:'Rival dens',raid:'Raid in progress',collection:'Bear book'};document.querySelector('#crumb').textContent=labels[page]||'Your den';document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page||page==='raid'&&b.dataset.page==='raidMap'));const v=document.querySelector('#view');v.innerHTML=page==='den'?denPage():page==='build'?buildPage():page==='train'?trainPage():page==='raidMap'?raidMapPage():page==='raid'?raidPage():collectionPage();wire();if(!localStorage.getItem(SAVE_KEY+'-welcomed'))welcome()}
function boardTile(x,y){const b=state.buildings.find(z=>z.x===x&&z.y===y),placing=Boolean(placement&&!b);if(!b)return `<button class="tile empty ${placing?'placing':''}" data-cell="${x},${y}" aria-label="Empty plot ${x+1}, ${y+1}">${placing?'<span class="micro">PLACE</span>':''}</button>`;const info=b.type==='home'?{name:'Family den',icon:'🏡'}:catalog[b.type];const rate=info.resource?`<span class="prod">+${Math.round(info.yield*(1+.35*(b.level-1)))}</span>`:'';return `<button class="tile ${selectedBuilding===b.id?'chosen':''}" data-building="${b.id}" aria-label="${esc(info.name)}, level ${b.level}"><span class="level">L${b.level}</span>${rate}<span><span class="emoji">${info.icon}</span><b>${esc(info.name)}</b>${b.type!=='home'?`<small>LV ${b.level}</small>`:''}</span></button>`}
function buildingInspector(){const b=findBuilding(selectedBuilding);if(!b)return `<div class="panelpad"><h2>Den report</h2><p>Choose a building to inspect it, or visit <b>Build</b> to add a new one. Your family gathers supplies at sundown.</p><div class="statline"><span>Building spots used</span><b>${state.buildings.length} / 48</b></div><div class="statline"><span>Home defense rating</span><b>${defenseScore()}</b></div><button class="btn primary" data-act="end-day">🌙 End day &amp; resolve night raid</button></div>`;if(b.type==='home')return `<div class="panelpad"><span class="pill">Family home</span><h2 style="margin-top:8px">Mosswood Den · Level ${b.level}</h2><p>Your den is the heart of the family. Gather supplies, plan raids, and make sure the lookout posts are ready before sundown.</p><div class="statline"><span>Night defense rating</span><b>${defenseScore()}</b></div><button class="btn gold" data-act="end-day">🌙 End day &amp; resolve night raid</button></div>`;const info=catalog[b.type],cost=upgradeCost(b),benefit=info.resource?`Produces +${Math.round(info.yield*(1+.35*(b.level-1)))} ${resourceInfo[info.resource].name} at night`:`${info.group==='Defense'?'Adds to home defense':'Improves den capacity'}`;return `<div class="panelpad"><div class="buildtop"><div class="buildicon">${info.icon}</div><div><h2>${info.name} · Level ${b.level}</h2><small>${esc(benefit)}</small></div></div><p>${info.desc}</p><div class="statline"><span>Upgrade cost</span><b>${storageText(cost)}</b></div><div class="buildfoot"><span class="capacity">${b.level>=4?'MAX LEVEL':`Level ${b.level} / 4`}</span><button class="btn primary" data-act="upgrade" data-building="${b.id}" ${b.level>=4?'disabled':''}>UPGRADE</button></div></div>`}
function denPage(){return `<div class="pagehead"><div><div class="eyebrow">DAY ${state.day} · HONEYFALL HARVEST</div><h1>Your den is taking shape.</h1><div class="sub">Grow the pantry, keep a lookout, and bring home supplies from neighboring bear families.</div></div><button class="btn ghost" data-page="raidMap">🗺 Scout rival dens</button></div>${placement?`<div class="modebanner"><span><b>${catalog[placement].name} selected.</b> Tap an empty plot to place it. Cost: ${storageText(catalog[placement].cost)}</span><button class="btn ghost" data-act="cancel-place">Cancel placement</button></div>`:''}<div class="grid twocol"><section class="card"><div class="cardhead"><h2>MOSSWOOD FAMILY DEN</h2><small>48 PLOTS · TAP A BUILDING TO INSPECT</small></div><div class="denmap"><div class="board">${Array.from({length:48},(_,i)=>boardTile(i%8,Math.floor(i/8))).join('')}</div></div></section><div class="stack"><section class="card">${buildingInspector()}</section><section class="card panelpad"><div class="cardhead" style="padding:0 0 8px"><h2>Tonight's supply forecast</h2><small>ONE GATHER PER DAY</small></div>${Object.entries(production()).map(([r,n])=>`<div class="statline"><span>${resourceInfo[r].icon} ${resourceInfo[r].name}</span><b>+${n} tonight</b></div>`).join('')||'<p>No producers yet. Build a gathering spot.</p>'}</section><section class="card panelpad"><h2>Den journal</h2>${state.history.slice(0,3).map(e=>`<div class="notice"><time>DAY ${e.day}</time>${esc(e.text)}</div>`).join('')||'<div class="notice">The cubs are drawing maps on toast and asking if it is raid day yet.</div>'}</section></div></div><div class="denbottom"><section class="card mission"><span class="pill">NEXT ADVENTURE</span><h3>${nextRival().name}</h3><p>${nextRival().description}</p><button class="btn primary" data-act="scout">OPEN RIVAL MAP　→</button></section><section class="card panelpad"><div class="micro">SQUAD READY</div><div class="squadbar">${Object.entries(state.squad).filter(([,n])=>n>0).map(([k,n])=>`<span class="squad-chip">${units[k].icon} ${units[k].name.split(' ')[0]} <b>×${n}</b></span>`).join('')||'<span class="squad-chip">No cubs selected yet</span>'}</div><button class="btn ghost" data-page="train">Adjust expedition squad</button></section></div><div class="footnote">Autosaves in this browser · Offline solo prototype · Project label: Codex / clash-of-cubs / base-builder-expansion</div>`}
function nextRival(){return rivals.find(r=>state.wins>=r.unlock)||rivals[0]}
function buildPage(){const grouped={};for(const [id,b]of Object.entries(catalog)){(grouped[b.group]??=[]).push([id,b])}return `<div class="pagehead"><div><div class="eyebrow">BUILD DEN · ${state.buildings.length}/48 PLOTS USED</div><h1>Choose a new den feature.</h1><div class="sub">Select a blueprint, then tap an open plot back at your den. Tap an existing building to upgrade it.</div></div><button class="btn ghost" data-page="den">← Back to den</button></div>${Object.entries(grouped).map(([group,items])=>`<h2 style="font-size:13px;margin:17px 0 9px">${group}</h2><div class="grid catalog">${items.map(([id,b])=>{const count=countType(id),limited=count>=b.max;return `<article class="card buildcard ${limited?'locked':''}"><div class="buildtop"><div class="buildicon">${b.icon}</div><div><h3>${b.name}</h3><small>${count}/${b.max} placed</small></div></div><p>${b.desc}</p><div class="buildfoot"><span class="cost">${storageText(b.cost)}</span><button class="btn primary" data-select-build="${id}" ${limited||!canPay(b.cost)?'disabled':''}>PLACE</button></div></article>`}).join('')}</div>`).join('')}<div class="footnote">Each den structure occupies one plot. Building limits encourage a balanced home.</div>`}
function trainPage(){const squadCap=3+buildingLevel('training')*2,ready=total(state.squad),cubCap=6+buildingLevel('nursery')*4;return `<div class="pagehead"><div><div class="eyebrow">NURSERY LEVEL ${buildingLevel('nursery')} · TRAINING GROVE LEVEL ${buildingLevel('training')}</div><h1>Pick your expedition crew.</h1><div class="sub">Train cubs for your den, then use plus and minus to choose who comes along. Your squad holds ${ready}/${squadCap} cubs.</div></div><button class="btn ghost" data-page="den">← Your den</button></div><div class="card panelpad" style="margin-bottom:15px"><div class="statline"><span>Den cub capacity</span><b>${total(state.roster)} / ${cubCap}</b></div><div class="squadbar">${Object.entries(state.squad).filter(([,n])=>n>0).map(([k,n])=>`<span class="squad-chip">${units[k].icon} ${units[k].name} <b>×${n}</b></span>`).join('')||'<span class="squad-chip">Choose cubs below</span>'}</div></div><div class="grid unitcards">${Object.entries(units).map(([id,u])=>`<article class="card unitcard"><div class="face">${u.icon}</div><h3>${u.name}</h3><span class="pill">${u.role}</span><p>${u.desc}</p><div class="speech">“${u.voice}”</div><div class="cost">IN DEN ${state.roster[id]||0} · ${storageText(u.cost)}</div><button class="btn primary" data-act="train" data-unit="${id}" ${total(state.roster)>=cubCap||!canPay(u.cost)?'disabled':''}>TRAIN A CUB</button><div class="unit-actions"><button class="btn ghost" data-act="squad-down" data-unit="${id}" ${!state.squad[id]?'disabled':''}>−</button><span class="capacity">SQUAD ${state.squad[id]||0}</span><button class="btn ghost" data-act="squad-up" data-unit="${id}" ${!state.roster[id]||state.squad[id]>=(state.roster[id]||0)||ready>=squadCap?'disabled':''}>+</button></div></article>`).join('')}</div><div class="speech"><b>Team tip:</b> Roller cubs break walls; Climbers skip over them; Screechers stun guards; Tunnel cubs emerge beside structures; wake Sleepy cubs before their big bonk.</div>`}
function raidMapPage(){return `<div class="pagehead"><div><div class="eyebrow">SCOUTING MAP · NEIGHBORING DENS</div><h1>Where will your cubs explore?</h1><div class="sub">Look at the target lineup and guard strength. Bring a squad with the right mix of specialists.</div></div><button class="btn ghost" data-page="den">← Your den</button></div><div class="grid rivalgrid">${rivals.map(r=>{const open=state.wins>=r.unlock;return `<article class="card rival ${open?'':'locked'}"><div class="eyebrow">${r.difficulty} ${open?'':'· WIN '+r.unlock+' TO UNLOCK'}</div><div class="enemy-preview">${r.mark} ${r.targets.slice(0,4).map(t=>t.icon).join(' ')}</div><h3>${r.name}</h3><p>${r.description}<br>${r.targets.filter(t=>t.kind==='guard').length} lookout · ${r.targets.filter(t=>t.kind==='wall').length} barriers · ${r.targets.filter(t=>t.objective).length} loot spots</p><button class="btn ${open?'primary':'ghost'}" data-act="start-raid" data-rival="${r.id}" ${open&&readySquad()? '':'disabled'}>${open?'SCOUT THIS DEN':'DEN LOCKED'}</button></article>`}).join('')}</div><div class="card panelpad" style="margin-top:15px"><h2>Before you go</h2><p>Bring a selected squad from the nursery. A raid ends when you clear two loot spots, all cubs have acted, or the squad is exhausted. Surviving cubs return home; a cub lost in a story event is remembered in the Bear Book.</p><button class="btn ghost" data-page="train">Review expedition squad</button></div>`}
function readySquad(){return total(state.squad)>0}
function raidPage(){const r=rivals.find(x=>x.id===state.activeRaid.rival)||rivals[0],a=state.activeRaid;return `<div class="pagehead"><div><div class="eyebrow">RAID ${a.round} · ${r.difficulty.toUpperCase()}</div><h1>${r.name}</h1><div class="sub">Choose a cub, tap a target, then send them in. Two cleared loot spots bring a full haul.</div></div><button class="btn ghost" data-act="retreat">↩ Retreat</button></div><div class="grid raidlayout"><section class="card"><div class="cardhead"><h2>SCOUTED DEN</h2><small>${a.objectivesCleared}/2 LOOT SPOTS CLEARED</small></div><div class="mapbg"><div class="enemyboard">${a.targets.map(t=>`<button class="target ${t.hp<=0?'destroyed':''} ${selectedTarget===t.id?'chosen':''}" data-target="${t.id}" ${t.hp<=0?'disabled':''}><span class="emoji">${t.icon}</span>${t.guard?'<span class="guard">🐾</span>':''}<b>${t.name}</b><small>${t.hp<=0?'CLEARED':`STAMINA ${t.hp}/${t.maxHp}`}</small><span class="hp"><i style="width:${Math.max(0,t.hp/t.maxHp*100)}%"></i></span></button>`).join('')}</div></div></section><section class="card deploypanel"><h2>Squad field notes</h2><div class="speech">${esc(a.dialogue||'Scout Pip whispers: “That lookout keeps pacing. We can be clever about this.”')}</div><div class="pick">${a.troops.filter(t=>!t.used&&!t.lost).map(t=>`<button data-troop="${t.id}" class="${selectedTroop===t.id?'selected':''}"><span class="face">${units[t.type].icon}</span><span>${units[t.type].name}<small>${t.hp} stamina · ${units[t.type].role}</small></span></button>`).join('')||'<div class="notice">No cubs are ready to deploy.</div>'}</div><button class="btn gold" data-act="wake-sleepy" ${!a.troops.some(t=>!t.used&&t.type==='sleepy')||a.sleepyReady?'disabled':''}>☀ Wake a Sleepy cub</button><p class="capacity">${a.sleepyReady?'Sleepy cub is ready for a big move.':'Wake one before deploying to charge its next attack.'}</p><button class="btn primary" data-act="deploy" ${selectedTroop&&selectedTarget?'':'disabled'}>SEND SELECTED CUB　→</button><div class="battlelog"><div class="micro">FIELD NOTES</div>${a.notes.slice(0,7).map(n=>`<div>${esc(n)}</div>`).join('')||'<div>The cubs crouch behind a fern. One tail is still sticking out.</div>'}</div></section></div><div class="footnote">Raids are scripted and offline. Loot from destroyed targets joins your den after the raid.</div>`}
function collectionPage(){return `<div class="pagehead"><div><div class="eyebrow">BEAR BOOK · ${state.collection.length}/5 MET</div><h1>Every cub has a story.</h1><div class="sub">Your collection remembers the cubs you trained, their voices, and the littermates lost along the way.</div></div><button class="btn ghost" data-page="den">← Your den</button></div><div class="grid unitcards">${Object.entries(units).map(([id,u])=>`<article class="card unitcard"><div class="face">${u.icon}</div><h3>${u.name}</h3><span class="pill">${state.collection.includes(id)?'MET IN MOSSWOOD':'NOT YET MET'}</span><p>${u.desc}</p><div class="speech">“${u.voice}”</div><div class="cost">IN DEN ${state.roster[id]||0}</div></article>`).join('')}</div><div class="card panelpad" style="margin-top:15px"><h2>Family journal</h2><div class="statline"><span>Rival dens explored</span><b>${state.wins}</b></div><div class="statline"><span>Lost cubs remembered</span><b>${state.casualties}</b></div><p>Storybook raids can include loss, fear, anger, and grief. The scenes stay non-graphic.</p><button class="btn ghost" data-act="reset">Reset this browser save</button></div>`}
function buildCost(b){return Object.fromEntries(Object.entries(catalog[b.type].cost).map(([r,n])=>[r,Math.ceil(n*b.level)]))}
function upgradeCost(b){return buildCost(b)}
function production(){const out={};for(const b of state.buildings){const info=catalog[b.type];if(info?.resource)out[info.resource]=(out[info.resource]||0)+Math.round(info.yield*(1+.35*(b.level-1)))}return out}
function defenseScore(){return countType('wall')*5+buildingLevel('guard')*9+buildingLevel('trap')*6+buildingLevel('storage')*2}
function maxCubCount(){return 6+buildingLevel('nursery')*4}
function chooseBuild(type){if(!catalog[type])return;if(countType(type)>=catalog[type].max){toast('You have placed the limit for that building.');return}if(state.buildings.length>=48){toast('All den plots are full.');return}if(!canPay(catalog[type].cost)){toast('Gather more supplies before placing that building.');return}placement=type;page='den';selectedBuilding=null;selectedTroop=null;selectedTarget=null;render();toast(`Tap an open plot to place ${catalog[type].name}.`)}
function placeBuilding(cell){if(!placement)return;const [x,y]=cell.split(',').map(Number);if(state.buildings.some(b=>b.x===x&&b.y===y)){toast('That plot is occupied. Choose an empty plot.');return}const type=placement,info=catalog[type];if(!info||countType(type)>=info.max||state.buildings.length>=48){toast('That building cannot be placed there.');return}if(!pay(info.cost)){toast('You need more supplies for that build.');return}const b={id:state.nextBuildId++,type,x,y,level:1};state.buildings.push(b);selectedBuilding=b.id;placement=null;addHistory(`${info.name} placed. ${info.resource?`It can gather ${resourceInfo[info.resource].name.toLowerCase()} each night.`:'The den gained a new strategic feature.'}`);render();toast(`${info.name} is ready!`)}
function upgradeBuilding(id){const b=findBuilding(id);if(!b||b.type==='home')return;if(b.level>=4){toast('That building is already at max level.');return}const cost=buildCost(b);if(!pay(cost)){toast('Not enough supplies to upgrade this building.');return}b.level++;addHistory(`${catalog[b.type].name} reached level ${b.level}.`);render();toast(`${catalog[b.type].name} upgraded to level ${b.level}.`)}
function trainUnit(type){if(!units[type])return;if(total(state.roster)>=maxCubCount()){toast('The nursery is full. Upgrade it to make room for more cubs.');return}if(!pay(units[type].cost)){toast('Not enough supplies to train that cub.');return}state.roster[type]=(state.roster[type]||0)+1;if(!state.collection.includes(type))state.collection.push(type);save();render();toast(`${units[type].name} joined the den!`)}
function changeSquad(type,delta){const cap=3+buildingLevel('training')*2,current=total(state.squad),selected=state.squad[type]||0,owned=state.roster[type]||0;if(delta>0&&(current>=cap||selected>=owned)){toast(current>=cap?'The squad is full. Upgrade the Training Grove for more spots.':'Train another cub of that type first.');return}if(delta<0&&selected<=0)return;state.squad[type]=selected+delta;save();render()}
function startRaid(id){const rival=rivals.find(r=>r.id===id);if(!rival||state.wins<rival.unlock){toast('Explore an easier den first to unlock this trail.');return}if(!readySquad()){toast('Choose at least one cub for the expedition.');showPage('train');return}state.activeRaid={rival:id,round:state.wins+1,targets:rival.targets.map(t=>({...t,maxHp:t.hp})),troops:Object.entries(state.squad).flatMap(([type,n])=>Array.from({length:n},(_,i)=>({id:`${type}-${i+1}`,type,hp:units[type].hp,used:false,lost:false}))),loot:{honey:0,berries:0,fish:0,toys:0,wood:0},notes:[],dialogue:'Scout Pip whispers: “We have a map, a snack, and a plan. More or less.”',objectivesCleared:0,usedTurns:0,sleepyReady:false,stunned:false};selectedTroop=null;selectedTarget=null;showPage('raid');save()}
function resolveDeploy(){const a=state.activeRaid;if(!a||!selectedTroop||!selectedTarget)return;const troop=a.troops.find(t=>t.id===selectedTroop&&!t.used&&!t.lost),target=a.targets.find(t=>t.id===selectedTarget&&t.hp>0);if(!troop||!target){toast('Choose an available cub and a standing target.');return}const type=troop.type;let damage=units[type].damage,extra='',guard=a.targets.some(t=>t.guard&&t.hp>0),walls=a.targets.some(t=>t.kind==='wall'&&t.hp>0),bypass=false;
  if(type==='roller'&&target.kind==='wall'){damage+=23;extra=' Roller cub crashes straight through the wall!'}
  if(type==='climber'&&target.kind==='loot'&&walls){damage+=8;bypass=true;extra=' Climber cub scales the wall and slips past the guard!'}
  if(type==='tunnel'&&target.kind==='wall'){damage+=20;extra=' Tunnel cub burrows under the barrier!'}
  if(type==='tunnel'&&target.kind!=='wall'){damage+=12;extra=' Tunnel cub emerges underneath the structure!'}
  if(type==='sleepy'){if(a.sleepyReady){damage+=26;extra=' A littermate wakes the Sleepy cub at the perfect moment!';a.sleepyReady=false}else{damage=9;extra=' Sleepy cub yawns through a weak little bonk.'}}
  if(type==='screecher'&&guard){a.stunned=true;extra=' Screecher cub stuns the lookout with a mighty holler!'}
  troop.used=true;a.usedTurns++;target.hp=Math.max(0,target.hp-damage);a.notes.unshift(`${units[type].icon} ${units[type].name}: “${units[type].voice}”${extra} ${target.name} loses ${damage} stamina.`);a.dialogue=type==='sleepy'&&a.sleepyReady?'Sleepy cub is waiting for the right moment.':`${units[type].name} made their move. The litter watches from the fern line.`;
  if(target.hp<=0){a.notes.unshift(`${target.name} cleared!`);if(target.objective)a.objectivesCleared++;for(const [r,n]of Object.entries(target.loot||{}))a.loot[r]+=n}
  if(guard&&!a.stunned&&!bypass&&target.hp>0){const living=a.targets.filter(t=>t.guard&&t.hp>0).length;const hit=12+living*12;troop.hp-=hit;a.notes.unshift(`The lookout counters for ${hit} stamina. ${units[type].name} ${troop.hp>0?'scrambles behind a stump.':'falls while the litter races to help.'}`);if(troop.hp<=0){troop.lost=true;a.notes.unshift(`A quiet shock runs through the team. A littermate fell; the others are frightened and grieving.`)}}else if(a.stunned){a.notes.unshift('The guard blinks and forgets what they were doing.');a.stunned=false}
  if(troop.lost)state.casualties++;
  selectedTroop=null;selectedTarget=null;save();const living=a.troops.filter(t=>!t.lost).length,win=a.objectivesCleared>=2,allUsed=a.troops.every(t=>t.used||t.lost);if(win||allUsed||a.usedTurns>=6){finishRaid(win)}else render();
}
function finishRaid(win){const a=state.activeRaid;if(!a)return;const share=win?1:.45;let gathered={};for(const [r,n]of Object.entries(a.loot)){const amount=Math.floor(n*share),overflow=addSupply(r,amount);gathered[r]=amount-overflow}if(win){state.wins++;const woodOverflow=addSupply('wood',18);gathered.wood=(gathered.wood||0)+18-woodOverflow;addHistory(`${rivals.find(r=>r.id===a.rival).name} explored. The cubs returned with a haul of supplies.`)}else addHistory(`The expedition turned back early. The cubs brought home part of the supplies they found.`);for(const t of a.troops)if(t.lost)state.roster[t.type]=Math.max(0,(state.roster[t.type]||0)-1);for(const key of Object.keys(state.squad))state.squad[key]=Math.min(state.squad[key]||0,state.roster[key]||0);state.activeRaid=null;save();const loot=Object.entries(gathered).filter(([,n])=>n>0).map(([r,n])=>`${resourceInfo[r].icon} ${n}`).join(' · ')||'No supplies carried home';document.querySelector('#modalroot').innerHTML=`<div class="overlay"><div class="modal"><div class="hero">${win?'🎒':'🍂'}</div><div class="eyebrow">${win?'RAID COMPLETE':'RAID OVER'}</div><h2>${win?'The cubs made it home!':'A brave try, little ones.'}</h2><p>${win?'The litter tumbles into the den, tired and proud. “I was scared, but I was not alone!”':'Pip holds a leaf beside the fern. “I’m scared. I’m mad. I miss them.” The loss is remembered without a graphic scene.'}</p><div class="battlelog">${a.notes.slice(0,4).map(n=>`<div>${esc(n)}</div>`).join("")}</div><div class="speech"><b>Pack:</b> ${esc(loot)}</div><button class="btn primary" data-dismiss>Return to the den</button></div></div>`;document.querySelector('[data-dismiss]').onclick=()=>{document.querySelector('#modalroot').innerHTML='';showPage('den')}
}
function homeDefense(){const threat=12+state.day*3,defense=defenseScore(),gap=Math.max(0,threat-defense);let stolen=0,res='honey';if(gap>0){if(state.resources.honey<1)res='berries';stolen=Math.min(state.resources[res]||0,gap*2);state.resources[res]-=stolen}const gathered=production(),overflow={};for(const [r,n]of Object.entries(gathered))overflow[r]=addSupply(r,n);state.day++;const result=gap===0?'The lookout, walls, and den traps chased off the night visitors. Your stores are safe.':`The night visitors slipped past the defenses and took ${stolen} ${resourceInfo[res].name.toLowerCase()}.`;const clipped=Object.entries(overflow).filter(([,n])=>n>0).map(([r,n])=>`${n} ${resourceInfo[r].name.toLowerCase()} overflowed`);addHistory(`${result} Gathered ${Object.entries(gathered).map(([r,n])=>`+${n} ${resourceInfo[r].name.toLowerCase()}`).join(', ')}.${clipped.length?' '+clipped.join(', ')+'.':''}`);save();render();document.querySelector('#modalroot').innerHTML=`<div class="overlay"><div class="modal"><div class="hero">${gap===0?'🌙':'🪶'}</div><div class="eyebrow">DAY ${state.day-1} · NIGHT PATROL</div><h2>${gap===0?'The den held safe.':'A little got away.'}</h2><p>${esc(result)}</p><div class="speech"><b>Gathered:</b> ${Object.entries(gathered).map(([r,n])=>`${resourceInfo[r].icon} +${n}`).join('　')||'No producers yet'}<br><b>Defense rating:</b> ${defense} / ${threat} needed</div><button class="btn primary" data-dismiss>Start day ${state.day}</button></div></div>`;document.querySelector('[data-dismiss]').onclick=()=>document.querySelector('#modalroot').innerHTML=''}
function action(action,el){if(action==='cancel-place'){placement=null;render()}if(action==='upgrade')upgradeBuilding(el.dataset.building);if(action==='train')trainUnit(el.dataset.unit);if(action==='squad-up')changeSquad(el.dataset.unit,1);if(action==='squad-down')changeSquad(el.dataset.unit,-1);if(action==='start-raid')startRaid(el.dataset.rival);if(action==='deploy')resolveDeploy();if(action==='wake-sleepy'){if(state.activeRaid?.troops.some(t=>t.type==='sleepy'&&!t.used&&!t.lost)){state.activeRaid.sleepyReady=true;state.activeRaid.dialogue='A littermate gently taps the Sleepy cub awake. “Your moment is coming.”';save();render()}}if(action==='end-day')homeDefense();if(action==='scout')showPage('raidMap');if(action==='retreat'){if(window.confirm('Turn back now? The cubs will bring home part of the supplies already found.'))finishRaid(false)}if(action==='reset'&&window.confirm('Clear this browser save and start over?')){localStorage.removeItem(SAVE_KEY);localStorage.removeItem(SAVE_KEY+'-welcomed');state=initial();page='den';render()}}
function wire(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>showPage(b.dataset.page));document.querySelectorAll('[data-select-build]').forEach(b=>b.onclick=()=>chooseBuild(b.dataset.selectBuild));document.querySelectorAll('[data-building]').forEach(b=>b.onclick=()=>{selectedBuilding=Number(b.dataset.building);placement=null;render()});document.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>placeBuilding(b.dataset.cell));document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>action(b.dataset.act,b));document.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{selectedTarget=b.dataset.target;render()});document.querySelectorAll('[data-troop]').forEach(b=>b.onclick=()=>{selectedTroop=b.dataset.troop;render()});document.querySelectorAll('[data-rival]').forEach(b=>b.onclick=()=>{action('start-raid',b)})}
function welcome(){document.querySelector('#modalroot').innerHTML=`<div class="overlay"><div class="modal"><div class="hero">🐻</div><div class="eyebrow">MOSSWOOD VALLEY · DAY ONE</div><h2>Welcome to the family den.</h2><p>Place gathering spots and defenses, then train a squad for one of the nearby rival dens. At night, producers gather supplies and your home defenses face a scripted visit.</p><p><b>How to play:</b> Build: choose a blueprint, then tap an open diamond plot. Train: recruit cubs and adjust your squad. Raid: choose a rival, select a cub, then choose a trail edge. Cub units fight on their own after deployment. Surviving cubs come home; the Bear Book remembers the story.</p><button class="btn primary" data-dismiss>Let's explore Mosswood</button></div></div>`;document.querySelector('[data-dismiss]').onclick=()=>{document.querySelector('#modalroot').innerHTML='';localStorage.setItem(SAVE_KEY+'-welcomed','yes')}}
// Village map art and layout: original SVG-built storybook scenery, no external assets.
function isoPoint(x,y){return [480+(x-y)*51,72+(x+y)*28]}
function isoTile(x,y){const [cx,cy]=isoPoint(x,y),w=51,h=28,occupied=state.buildings.some(b=>b.x===x&&b.y===y),pts=`${cx},${cy-h} ${cx+w},${cy} ${cx},${cy+h} ${cx-w},${cy}`;return `<polygon class="iso-tile ${occupied?'occupied':''} ${placement&&!occupied?'placeable':''}" points="${pts}" data-cell="${x},${y}" aria-label="${occupied?'Occupied':'Empty'} den plot ${x+1}, ${y+1}"/>`}
function buildingSprite(type){if(type==='home')return `<ellipse cx="0" cy="15" rx="37" ry="14" fill="#34503955"/><path d="M-30 -8L0 8 30-8v25L0 35-30 19Z" fill="#9b643c" stroke="#5c412e" stroke-width="2"/><path d="M0 8L30-8 30 17 0 35Z" fill="#754b33" stroke="#5c412e" stroke-width="2"/><path d="M-34-10L0-32 34-10 0 9Z" fill="#d68b4d" stroke="#74472c" stroke-width="2.5"/><path d="M-34-10L0 9v5l-34-19Z" fill="#af633b"/><path d="M-24-10L0-26 24-10 0 4Z" fill="#f1b566"/><path d="M-7 16q7-9 14 0v19H-7Z" fill="#52382c"/><circle cx="-19" cy="5" r="5" fill="#eac48b"/><circle cx="21" cy="5" r="5" fill="#eac48b"/><path d="M-25-14l3-12 6 10M8-26l5-12 7 14" fill="#76503a"/><path d="M-2-31q2-10 8 0" fill="#fff1c7"/><circle cx="3" cy="-29" r="1.3" fill="#38291e"/><circle cx="8" cy="-29" r="1.3" fill="#38291e"/>`;
if(type==='wall')return `<ellipse cx="0" cy="11" rx="29" ry="9" fill="#394b3555"/><path d="M-27-5L0 9 27-5v13L0 22-27 9Z" fill="#59402f"/><path d="M-24-11L0 1 24-11 27-5 0 9-27-5Z" fill="#987048" stroke="#67472e" stroke-width="2"/><path d="M-22-16L-2-5 19-17 25-11 2 2-23-11Z" fill="#ae8051" stroke="#67472e" stroke-width="2"/><path d="M-18-15l5 2m17 6l5-3" stroke="#e2bd82" stroke-width="2"/>`;
if(type==='guard')return `<ellipse cx="0" cy="15" rx="30" ry="11" fill="#34503955"/><path d="M-20 0L0 11 20 0v19L0 31-20 19Z" fill="#79543a"/><path d="M-19-9L0 2 19-9v7L0 9-19-2Z" fill="#a77546" stroke="#60432d" stroke-width="2"/><path d="M-15-25h30v7h-30Z" fill="#be8950" stroke="#60432d" stroke-width="2"/><path d="M-14-24v25M14-24v25M-7-24v25M7-24v25" stroke="#65452d" stroke-width="3"/><circle cx="0" cy="-17" r="11" fill="#8b5c3d"/><circle cx="-8" cy="-26" r="5" fill="#8b5c3d"/><circle cx="8" cy="-26" r="5" fill="#8b5c3d"/><circle cx="-4" cy="-18" r="1.5" fill="#211b17"/><circle cx="4" cy="-18" r="1.5" fill="#211b17"/><ellipse cx="0" cy="-13" rx="4" ry="3" fill="#e8c997"/><path d="M-3-13h6" stroke="#33251d" stroke-width="1.5"/>`;
if(type==='berry')return `<ellipse cx="0" cy="14" rx="32" ry="11" fill="#34503955"/><path d="M-28 11q-8-13 4-22 6-14 18-7 12-14 22 0 16-4 16 12 9 13-3 22Z" fill="#64854f" stroke="#49653b" stroke-width="2"/><path d="M-20 7q1-16 15-18 12-12 22 0 13 3 11 17" fill="#789d5e"/><circle cx="-14" cy="-6" r="6" fill="#a94562"/><circle cx="2" cy="-15" r="6" fill="#c15168"/><circle cx="16" cy="-5" r="6" fill="#99425e"/><path d="M-16-12l3-4 3 4M0-21l3-4 3 4M14-11l3-4 3 4" fill="#8bad61"/>`;
if(type==='pond')return `<ellipse cx="0" cy="10" rx="34" ry="21" fill="#7d6946" stroke="#554937" stroke-width="3"/><ellipse cx="0" cy="5" rx="27" ry="15" fill="#77b9bf" stroke="#e0d19c" stroke-width="3"/><path d="M-18 2q10-7 20 0-10 8-20 0Zm17 0 7-6v12Z" fill="#f3bb58"/><circle cx="-12" cy="0" r="1.3" fill="#382b20"/><path d="M-12-2q8-8 15-2M5 9q7-3 13 0" stroke="#d5f1dc" stroke-width="2" fill="none"/>`;
if(type==='hive')return `<ellipse cx="0" cy="13" rx="27" ry="10" fill="#34503955"/><path d="M-23 8q-7-6-2-12 2-5 8-5-1-9 8-11 2-9 11-3 11-4 13 6 9 3 7 11 8 7 0 14Z" fill="#e6b64e" stroke="#9d7332" stroke-width="2.5"/><path d="M-14-4q14 5 28 0M-10-15q11 5 22 0" stroke="#bf8739" stroke-width="3" fill="none"/><path d="M-6 14q6-7 12 0v7H-6Z" fill="#6c492d"/><circle cx="22" cy="-19" r="5" fill="#f3c644"/><path d="M19-23q-5-7-8-2m15 1q5-6 8-1" stroke="#4e5b3a" stroke-width="2" fill="none"/>`;
if(type==='toyshop'||type==='nursery')return `<ellipse cx="0" cy="14" rx="32" ry="11" fill="#34503955"/><path d="M-27-4L0 10 27-4v22L0 34-27 20Z" fill="${type==='nursery'?'#bd8050':'#ce8060'}" stroke="#6c4b36" stroke-width="2"/><path d="M0 10L27-4v22L0 34Z" fill="#9c6149" stroke="#6c4b36" stroke-width="2"/><path d="M-32-7L0-29 32-7 0 11Z" fill="${type==='nursery'?'#638553':'#bb6255'}" stroke="#65432f" stroke-width="2.5"/><path d="M-20-7L0-21 20-7 0 4Z" fill="#e1a968"/><path d="M-7 18q7-8 14 0v14H-7Z" fill="#523b2d"/><rect x="-22" y="4" width="9" height="8" rx="2" fill="#f5d28f"/><rect x="12" y="4" width="9" height="8" rx="2" fill="#f5d28f"/>${type==='toyshop'?'<circle cx="0" cy="-37" r="7" fill="#dfad70"/><circle cx="-6" cy="-43" r="4" fill="#dfad70"/><circle cx="6" cy="-43" r="4" fill="#dfad70"/><circle cx="-2" cy="-37" r="1" fill="#33261f"/><circle cx="2" cy="-37" r="1" fill="#33261f"/>':''}`;
if(type==='mill')return `<ellipse cx="0" cy="14" rx="32" ry="11" fill="#34503955"/><path d="M-26 0L0 13 26 0v19L0 34-26 19Z" fill="#98643f" stroke="#64432e" stroke-width="2"/><path d="M0 13L26 0v19L0 34Z" fill="#754b36" stroke="#64432e" stroke-width="2"/><path d="M-31-3L0-24 31-3 0 15Z" fill="#b47545" stroke="#64432e" stroke-width="2.5"/><path d="M-21-4L0-18 21-4 0 8Z" fill="#d19a58"/><circle cx="22" cy="9" r="11" fill="#bd8b53" stroke="#714b2e" stroke-width="3"/><circle cx="22" cy="9" r="3" fill="#60432e"/><path d="M22-2v22M11 9h22" stroke="#714b2e" stroke-width="2"/>`;
if(type==='storage')return `<ellipse cx="0" cy="14" rx="29" ry="10" fill="#34503955"/><path d="M-22-13q0-9 22-9t22 9v29q-2 9-22 9t-22-9Z" fill="#b27c43" stroke="#694a2f" stroke-width="2.5"/><ellipse cx="0" cy="-13" rx="22" ry="8" fill="#d2a35f" stroke="#694a2f" stroke-width="2"/><path d="M-18-6v22m9-24v28m18-28v28m9-25v22" stroke="#765331" stroke-width="3"/><path d="M-21 0h42M-20 12h40" stroke="#e0bb7a" stroke-width="2"/><ellipse cx="0" cy="-13" rx="12" ry="4" fill="#765331"/>`;
if(type==='training')return `<ellipse cx="0" cy="15" rx="29" ry="10" fill="#34503955"/><path d="M-20 12L-7-18M20 12L7-18M-25 12h50" stroke="#795438" stroke-width="4"/><circle cx="0" cy="-20" r="19" fill="#ead8a1" stroke="#845f3c" stroke-width="3"/><circle cx="0" cy="-20" r="12" fill="#bb6459"/><circle cx="0" cy="-20" r="5" fill="#edb94d"/><path d="M12-34l16-8" stroke="#755136" stroke-width="3"/><path d="M27-43l5 5" stroke="#a15d42" stroke-width="4"/>`;
if(type==='trap')return `<ellipse cx="0" cy="13" rx="28" ry="9" fill="#34503955"/><path d="M-24 4L-15-19 15-19 24 4 0 18Z" fill="#b77d43" stroke="#68472f" stroke-width="2.5"/><path d="M-15-18L0-5 15-18M-20-8L0 6 20-8" stroke="#e1ae67" stroke-width="3"/><path d="M-5 18v-9q5-7 10 0v9" fill="none" stroke="#66452e" stroke-width="3"/><path d="M-25 5q-8 6-3 12m53-12q8 6 3 12" stroke="#786047" stroke-width="3"/>`;
return `<ellipse cx="0" cy="13" rx="26" ry="9" fill="#34503955"/><path d="M-21-8L0 4 21-8v19L0 23-21 11Z" fill="#a97e50" stroke="#65492f" stroke-width="2"/><path d="M-24-10L0-27 24-10 0 5Z" fill="#c3965d" stroke="#65492f" stroke-width="2"/>`}
function isoBuilding(b){const [x,y]=isoPoint(b.x,b.y),info=b.type==='home'?{name:'Family den',icon:'🏡'}:catalog[b.type],selected=selectedBuilding===b.id,sort=b.x+b.y;return `<g class="iso-building ${selected?'selected':''} type-${b.type}" transform="translate(${x} ${y}) scale(1.25)" style="z-index:${sort}" data-building="${b.id}" role="button" tabindex="0" aria-label="${esc(info.name)} level ${b.level}"><g class="sprite">${buildingSprite(b.type)}</g>${selected?`<g class="building-nameplate"><rect x="-49" y="38" width="98" height="20" rx="8"/><text x="0" y="52" text-anchor="middle">${esc(info.name)} · LV ${b.level}</text></g>${info.resource?`<g class="building-yield"><rect x="-28" y="-59" width="56" height="18" rx="8"/><text x="0" y="-46" text-anchor="middle">+${Math.round(info.yield*(1+.35*(b.level-1)))}/night</text></g>`:''}`:''}</g>`}
function ambientCub(x,y,color,delay=0){const[cx,cy]=isoPoint(x,y);return `<g class="cub-ambient" transform="translate(0 0)"><animateTransform attributeName="transform" type="translate" values="${cx} ${cy-2};${cx} ${cy-5};${cx} ${cy-2}" dur="2.7s" begin="${delay}s" repeatCount="indefinite"/><ellipse cx="0" cy="12" rx="10" ry="4" fill="#33483255"/><ellipse cx="0" cy="5" rx="7" ry="9" fill="${color}" stroke="#624532" stroke-width="1.3"/><circle cx="0" cy="-5" r="8" fill="${color}" stroke="#624532" stroke-width="1.3"/><circle cx="-6" cy="-11" r="3.2" fill="${color}" stroke="#624532" stroke-width="1.2"/><circle cx="6" cy="-11" r="3.2" fill="${color}" stroke="#624532" stroke-width="1.2"/><ellipse cx="0" cy="-3" rx="4.4" ry="3.2" fill="#e7c99c"/><circle cx="-2.7" cy="-6" r="1" fill="#211a16"/><circle cx="2.7" cy="-6" r="1" fill="#211a16"/><ellipse cx="0" cy="-3.3" rx="1.6" ry="1.1" fill="#36241c"/><path d="M-3 2q3 2 6 0" fill="none" stroke="#f2d8af" stroke-width="2"/></g>`}
function villageMap(){const tiles=Array.from({length:48},(_,i)=>isoTile(i%8,Math.floor(i/8))).join(''),trees=[[0,1],[0,5],[1,5],[7,0],[7,4],[6,5],[2,5],[5,5],[0,0],[7,5]].filter(([x,y])=>!state.buildings.some(b=>Math.abs(b.x-x)<=1&&Math.abs(b.y-y)<=1)).map(([x,y],i)=>{const [cx,cy]=isoPoint(x,y);return `<g class="tree" transform="translate(${cx} ${cy-28})"><ellipse cx="0" cy="24" rx="17" ry="6" fill="#345b3a55"/><path d="M0 -6 L-15 20 L15 20Z" fill="${i%2?'#567c48':'#668c50'}" stroke="#44693f" stroke-width="2"/><path d="M0 1 L-11 23 L11 23Z" fill="#789b5d"/><rect x="-3" y="20" width="6" height="13" rx="2" fill="#76583d"/></g>`}).join(''),cubs=[[0,5,'#9c704a',0],[7,5,'#bd8250',.8],[6,4,'#86634b',1.6]].map(([x,y,color,delay])=>ambientCub(x,y,color,delay)).join(''),buildings=state.buildings.slice().sort((a,b)=>(a.x+a.y)-(b.x+b.y)).map(isoBuilding).join('');return `<svg class="village-svg" viewBox="0 0 960 500" role="group" aria-label="Mosswood family den village map"><defs><linearGradient id="meadow" x2="0" y2="1"><stop stop-color="#95bd7a"/><stop offset="1" stop-color="#729c61"/></linearGradient><linearGradient id="roof" x2="0" y2="1"><stop stop-color="#e3a865"/><stop offset="1" stop-color="#a85e3c"/></linearGradient><filter id="islandShadow" x="-20%" y="-20%" width="140%" height="150%"><feDropShadow dx="0" dy="12" stdDeviation="8" flood-color="#294b34" flood-opacity=".32"/></filter></defs><path class="island" filter="url(#islandShadow)" d="M480 18 L907 254 L480 482 L53 254Z"/><path class="island-rim" d="M53 254 L480 482 L907 254"/><path class="village-path" d="M480 430 460 362 480 310 480 265M220 254 325 254 402 254M740 254 650 254 575 254"/>${Array.from({length:9},(_,i)=>`<circle class="flower" cx="${135+(i*87)%700}" cy="${92+(i*53)%320}" r="${i%3===0?3:2}"/>`).join('')}${tiles}${trees}${cubs}${buildings}</svg>`}
function boardTile(x,y){const b=state.buildings.find(z=>z.x===x&&z.y===y);return b?isoBuilding(b):''}
function denPage(){const home=findBuilding(selectedBuilding)||findBuilding(14);return `<section class="village-head"><div><div class="eyebrow">MOSSWOOD VALLEY · DAY ${state.day} · HONEYFALL HARVEST</div><h1>Your family den</h1><div class="sub">Build a cozy stronghold, grow your squad, then raid the rival trails.</div></div><div class="den-actions"><button class="btn gold attack-button" data-act="scout">⚔ ATTACK!</button><button class="btn ghost" data-act="end-day">🌙 End day</button></div></section>${placement?`<div class="modebanner"><span><b>${catalog[placement].name} selected.</b> Tap an open meadow plot. Cost: ${storageText(catalog[placement].cost)}</span><button class="btn ghost" data-act="cancel-place">Cancel</button></div>`:''}<section class="village-frame"><div class="village-toolbar"><div><b>MOSSWOOD FAMILY DEN</b><small>Tap a building to inspect · choose Build to place new structures</small></div><div class="village-stats"><span>🛠️ ${Math.min(2,Math.floor(state.buildings.length/8))}/2</span><span>🛡️ ${defenseScore()} den strength</span></div></div><div class="village-stage">${villageMap()}<div class="map-callout">🌲 The cubs are out gathering!</div></div></section><div class="village-lower"><section class="card build-strip"><div class="build-strip-head"><div><div class="eyebrow">DEN WORKSHOP</div><b>Grow your village</b></div><button class="btn ghost" data-page="build">OPEN BUILD MENU →</button></div><div class="quick-builds">${Object.entries(catalog).filter(([id])=>['hive','berry','pond','toyshop','mill','wall','guard','trap'].includes(id)).map(([id,v])=>`<button class="quick-build" data-select-build="${id}" title="${esc(v.desc)}"><span>${v.icon}</span><b>${v.name}</b><small>${countType(id)}/${v.max} · ${storageText(v.cost)}</small></button>`).join('')}</div></section><section class="card inspector-card">${home?buildingInspector():`<div class="panelpad"><h2>Den report</h2><p>Select a building to inspect or upgrade it.</p><button class="btn gold" data-act="end-day">🌙 End day &amp; resolve patrol</button></div>`}</section></div><section class="village-footer"><div class="squad-mini"><b>🧸 Expedition squad</b><div class="squadbar">${Object.entries(state.squad).filter(([,n])=>n>0).map(([k,n])=>`<span class="squad-chip">${units[k].icon} ${units[k].name.split(' ')[0]} <b>×${n}</b></span>`).join('')||'<span class="squad-chip">Train cubs to get ready</span>'}</div></div><button class="btn ghost" data-page="train">TRAIN CUBS</button><button class="btn ghost" data-page="raidMap">SCOUT RIVALS</button></section><div class="footnote">Offline den · Autosaves in this browser · ${esc(document.querySelector('#crumb')?.textContent||'Mosswood')}</div>`}
function raidMapPage(){return `<div class="pagehead"><div><div class="eyebrow">EXPEDITION TRAILS · RIVAL FAMILY DENS</div><h1>Pick a den to raid.</h1><div class="sub">Study each rival's layout, pick the right cubs, and bring home their supplies.</div></div><button class="btn ghost" data-page="den">← Home den</button></div><div class="grid rivalgrid">${rivals.map(r=>{const open=state.wins>=r.unlock;return `<article class="card rival ${open?'':'locked'}"><div class="enemy-preview">${r.mark} ${r.targets.slice(0,4).map(t=>t.icon).join(' ')}</div><div class="eyebrow">${r.difficulty} ${open?'':'· WIN '+r.unlock+' TO UNLOCK'}</div><h3>${r.name}</h3><p>${r.description}<br>${r.targets.filter(t=>t.kind==='guard').length} guard posts · ${r.targets.filter(t=>t.kind==='wall').length} walls · rewards across ${r.targets.filter(t=>t.objective).length} stores</p><button class="btn ${open?'gold':'ghost'}" data-act="start-raid" data-rival="${r.id}" ${open&&readySquad()?'':'disabled'}>${open?'⚔ ATTACK THIS DEN':'DEN LOCKED'}</button></article>`}).join('')}</div><div class="card panelpad" style="margin-top:15px"><h2>Choose your cubs</h2><p>Walls, guard posts, loot stores, and the family home all matter. Pick a specialist squad before you go.</p><button class="btn primary" data-page="train">PREPARE SQUAD</button></div>`}
function denPage(){const chosen=selectedBuilding?findBuilding(selectedBuilding):null;return `<section class="village-head"><div class="location-lockup"><span>🌲</span><div><div class="eyebrow">MOSSWOOD VALLEY · DAY ${state.day}</div><b>Mosswood Family Den</b></div></div><div class="village-day-actions"><span class="builder-count">🏘 ${state.buildings.length}/48 PLOTS</span><span class="defense-count">🛡 ${defenseScore()}</span></div></section>${placement?`<div class="modebanner"><span><b>${catalog[placement].name}</b> · Tap any glowing open clearing to place · Cost ${storageText(catalog[placement].cost)}</span><button class="btn ghost" data-act="cancel-place">CANCEL</button></div>`:''}<section class="village-frame"><div class="village-stage">${villageMap()}<div class="map-callout">${placement?'Choose a glowing plot':`🌼 ${state.buildings.length} den structures · ${countType('wall')} wall pieces`}</div>${chosen?`<div class="selected-building-panel"><button class="close-inspect" data-act="clear-selection" aria-label="Close building details">×</button>${buildingInspector()}</div>`:''}</div></section><section class="village-actionbar"><button class="btn gold attack-button" data-act="scout"><span class="action-icon">⚔</span><span><b>ATTACK!</b><small>${nextRival().name}</small></span></button><div class="hud-actions"><button class="hud-button" data-page="build"><span>🏗️</span><b>BUILD</b></button><button class="hud-button" data-page="train"><span>🐾</span><b>ARMY</b></button><button class="hud-button" data-page="collection"><span>📖</span><b>BEAR BOOK</b></button></div><button class="btn ghost end-day-button" data-act="end-day"><span>🌙</span><b>End day</b></button></section><div class="footnote">Offline village · Autosaves in this browser · Select a building to view or upgrade it</div>`}
function buildPage(){const cards=Object.entries(catalog).map(([id,b])=>{const count=countType(id),limited=count>=b.max;return `<button class="build-menu-item ${limited?'locked':''}" data-select-build="${id}" ${limited||!canPay(b.cost)?'disabled':''}><span class="menu-icon">${b.icon}</span><span class="menu-copy"><b>${b.name}</b><small>${b.group} · ${count}/${b.max} placed</small><em>${esc(b.desc)}</em></span><span class="menu-cost">${storageText(b.cost)}</span></button>`}).join('');return `${denPage()}<div class="scene-overlay"><button class="scene-dim" data-act="close-menu" aria-label="Close build menu"></button><section class="scene-panel"><header><div><div class="eyebrow">BUILDINGS · ${state.buildings.length}/48 PLOTS</div><h2>Build the den</h2><p>Pick a structure, then choose a glowing meadow plot.</p></div><button class="close-menu" data-page="den">×</button></header><div class="build-menu-list">${cards}</div></section></div>`}
function trainPage(){const squadCap=3+buildingLevel('training')*2,ready=total(state.squad),cubCap=6+buildingLevel('nursery')*4;return `${denPage()}<div class="scene-overlay"><button class="scene-dim" data-act="close-menu" aria-label="Close army menu"></button><section class="scene-panel army-panel"><header><div><div class="eyebrow">NURSERY ${buildingLevel('nursery')} · GROVE ${buildingLevel('training')}</div><h2>Raise your squad</h2><p>Den ${total(state.roster)}/${cubCap} · Squad ${ready}/${squadCap}</p></div><button class="close-menu" data-page="den">×</button></header><div class="army-menu-list">${Object.entries(units).map(([id,u])=>`<article class="army-menu-item"><span class="menu-icon">${u.icon}</span><div class="menu-copy"><b>${u.name} <small>×${state.roster[id]||0}</small></b><em>${u.desc}</em><div class="army-controls"><button class="btn ghost" data-act="squad-down" data-unit="${id}" ${!state.squad[id]?'disabled':''}>−</button><span>Squad ${state.squad[id]||0}</span><button class="btn ghost" data-act="squad-up" data-unit="${id}" ${!state.roster[id]||ready>=squadCap?'disabled':''}>+</button><button class="btn primary" data-act="train" data-unit="${id}" ${total(state.roster)>=cubCap||!canPay(u.cost)?'disabled':''}>TRAIN · ${storageText(u.cost)}</button></div></div></article>`).join('')}</div></section></div>`}
let battleClock=null;
const targetSpots=[[27,30],[68,25],[48,52],[25,67],[73,61],[53,34],[38,43],[62,44]];
let previousStartRaid=startRaid;startRaid=function(id){previousStartRaid(id);const a=state.activeRaid;if(!a)return;a.secondsLeft=75;a.guardStun=0;a.troops.forEach(t=>Object.assign(t,{deployed:false,edge:'south',progress:0,attackClock:0,targetId:null}));save();render()};
let previousFinishRaid=finishRaid;finishRaid=function(win){if(battleClock!==null){clearInterval(battleClock);battleClock=null}previousFinishRaid(win)};
function targetFor(t,a){const live=a.targets.filter(x=>x.hp>0);if(t.type==='roller'){const wall=live.find(x=>x.kind==='wall');if(wall)return wall}if(t.type==='screecher'){const guard=live.find(x=>x.guard);if(guard)return guard}if(t.type==='climber'||t.type==='tunnel'){const loot=live.find(x=>x.objective);if(loot)return loot}return live.find(x=>x.objective)||live[0]}
function raidTick(){const a=state.activeRaid;if(!a)return;if(!Number.isFinite(a.secondsLeft))a.secondsLeft=75;if(!Number.isFinite(a.guardStun))a.guardStun=0;if(a.secondsLeft<=0){finishRaid(a.objectivesCleared>=2);return}a.secondsLeft--;const guards=a.targets.filter(t=>t.guard&&t.hp>0).length;for(const t of a.troops){if(!t.deployed||t.lost)continue;let target=a.targets.find(x=>x.id===t.targetId&&x.hp>0);if(!target){target=targetFor(t,a);if(target)t.targetId=target.id}if(!target)continue;if(t.progress<3){t.progress++;continue}t.attackClock++;if(t.attackClock%2===0){let damage=units[t.type].damage;if(t.type==='roller'&&target.kind==='wall')damage+=18;if(t.type==='climber'&&target.kind==='loot')damage+=7;if(t.type==='tunnel')damage+=target.kind==='wall'?15:8;if(t.type==='screecher'&&guards){a.guardStun=Math.max(a.guardStun,2);damage+=4;a.notes.unshift('Screecher cub stuns the lookout with a mighty holler!')}if(t.type==='sleepy')damage=a.sleepyReady?damage+24:7;if(t.type==='sleepy'&&a.sleepyReady)a.sleepyReady=false;target.hp=Math.max(0,target.hp-damage);a.notes.unshift(`${units[t.type].icon} ${units[t.type].name} hits ${target.name} for ${damage}.${t.type==='roller'&&target.kind==='wall'?' The wall splinters!':''}`);if(target.hp===0){a.notes.unshift(`${target.name} falls!`);if(target.objective){a.objectivesCleared++;for(const[r,n]of Object.entries(target.loot||{}))a.loot[r]+=n}}}
    if(guards&&a.guardStun<=0&&t.attackClock%3===0){const hit=5+guards*4;t.hp-=hit;a.notes.unshift(`A lookout pelts ${units[t.type].name} for ${hit}.`);if(t.hp<=0){t.lost=true;t.used=true;state.casualties++;a.notes.unshift(`The litter huddles together. ${units[t.type].name} has fallen; the others are frightened and grieving.`)}}}
  if(a.guardStun>0)a.guardStun--;a.notes=a.notes.slice(0,14);save();if(a.objectivesCleared>=2){finishRaid(true);return}if(a.secondsLeft<=0)finishRaid(false);else render()}
function raidArena(a){const targets=a.targets.map((t,i)=>{const [x,y]=targetSpots[i%targetSpots.length];return `<button class="raid-target ${t.hp<=0?'destroyed':''} ${selectedTarget===t.id?'chosen':''}" data-target="${t.id}" style="left:${x}%;top:${y}%" ${t.hp<=0?'disabled':''}><span>${t.icon}</span>${t.guard?'<i>🐾</i>':''}<b>${esc(t.name)}</b><small>${t.hp<=0?'CLEARED':`${t.hp} stamina`}</small><em><u style="width:${Math.max(0,t.hp/t.maxHp*100)}%"></u></em></button>`}).join('');const troops=a.troops.filter(t=>t.deployed&&!t.lost).map(t=>{const spot=targetSpots[a.targets.findIndex(x=>x.id===t.targetId)]||[50,45],start=t.edge==='north'?[50,95]:t.edge==='west'?[5,55]:t.edge==='east'?[95,55]:[50,95],p=Math.min(1,t.progress/4),x=start[0]+(spot[0]-start[0])*p,y=start[1]+(spot[1]-start[1])*p;return `<span class="raid-cub" style="left:${x}%;top:${y}%" title="${units[t.type].name} · ${t.hp} stamina">${units[t.type].icon}</span>`}).join('');return `<div class="raid-arena">${Array.from({length:28},(_,i)=>`<i class="arena-tree" style="left:${(i*37+5)%96}%;top:${(i*61+9)%88}%">${i%3===0?'🌳':'🌿'}</i>`).join('')}<div class="enemy-camp">${a.targets.map(t=>t.kind==='wall'?`<span class="camp-wall">🪵</span>`:'').join('')}</div>${targets}${troops}<div class="raid-timer">⏱ ${String(Math.floor(a.secondsLeft/60)).padStart(2,'0')}:${String(a.secondsLeft%60).padStart(2,'0')}</div></div>`}
function raidPage(){const r=rivals.find(x=>x.id===state.activeRaid.rival)||rivals[0],a=state.activeRaid;if(battleClock===null&&typeof setInterval==='function')battleClock=setInterval(raidTick,1000);const available=a.troops.filter(t=>!t.deployed&&!t.lost&&!t.used),deployed=a.troops.filter(t=>t.deployed&&!t.lost);return `<div class="pagehead"><div><div class="eyebrow">EXPEDITION · ${a.objectivesCleared}/2 STORES LOOTED</div><h1>Raid ${r.name}</h1><div class="sub">Choose a cub, pick a trail edge, and watch the litter break into the den. Cub behavior and the guards run while you make your next move.</div></div><button class="btn ghost" data-act="retreat">↩ Retreat</button></div><section class="card raid-live"><div class="raid-live-head"><b>RIVAL DEN · LIVE RAID</b><span>Looted: ${Object.entries(a.loot).filter(([,n])=>n).map(([key,n])=>`${resourceInfo[key].icon} ${n}`).join(' · ')||'nothing yet'}</span></div>${raidArena(a)}<div class="raid-deploy"><div class="deploy-status"><b>Choose your next cub to deploy</b><small>${available.length} ready · ${deployed.length} on the field · ${a.troops.filter(t=>t.lost).length} lost</small></div><div class="live-troops">${a.troops.map(t=>`<button class="live-troop ${selectedTroop===t.id?'selected':''} ${t.deployed?'deployed':''} ${t.lost?'lost':''}" data-troop="${t.id}" ${t.lost||t.used||t.deployed?'disabled':''}><span>${units[t.type].icon}</span><b>${units[t.type].name}</b><small>${t.lost?'FELL':t.deployed?'ON FIELD':`${t.hp} stamina`}</small></button>`).join('')}</div><div class="edge-row"><span>Deploy along:</span>${['north','west','east','south'].map(edge=>`<button class="btn ${selectedTroop?'gold':'ghost'}" data-edge="${edge}" ${selectedTroop?'':'disabled'}>${edge==='north'?'🌲 Upper':edge==='west'?'🌿 Left':edge==='east'?'🌳 Right':'🍂 Lower'} trail</button>`).join('')}<button class="btn ghost" data-act="wake-sleepy" ${!available.some(t=>t.type==='sleepy')||a.sleepyReady?'disabled':''}>☀ Wake sleepy cub</button></div><div class="speech">${esc(a.dialogue||'The litter waits for your signal.')} ${a.guardStun>0?'A lookout is stunned!':''}</div><div class="battlelog">${a.notes.slice(0,5).map(n=>`<div>${esc(n)}</div>`).join('')||'<div>The den is quiet; scouts are watching for the cubs.</div>'}</div></div></section><div class="footnote">Choose deployment timing and trail. Cub specialists choose targets and fight on their own while guards retaliate.</div>`}
let previousAction=action;action=function(name,el){if(name==='clear-selection'){selectedBuilding=null;render();return}if(name==='close-menu'){showPage('den');return}if(name==='deploy-edge'){const a=state.activeRaid,t=a?.troops.find(x=>x.id===selectedTroop&&!x.deployed&&!x.lost);if(!t){toast('Choose a cub that is ready to deploy.');return}t.deployed=true;t.edge=el.dataset.edge;t.progress=0;t.targetId=targetFor(t,a)?.id||null;const cue={roller:'starts a wall-cracking tumble',climber:'scrambles up an elevated trail',screecher:'lets out a rattling battle cry',tunnel:'dives underground with a dirt puff',sleepy:a.sleepyReady?'wakes with a mighty bonk':'shuffles in with a sleepy yawn'};a.dialogue=`${units[t.type].name} ${cue[t.type]} from the ${t.edge} trail! “${units[t.type].voice}”`;a.notes.unshift(`${units[t.type].name} deployed from the ${t.edge} trail.`);selectedTroop=null;save();render();return}previousAction(name,el)};
function wire(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>showPage(b.dataset.page));document.querySelectorAll('[data-select-build]').forEach(b=>b.onclick=()=>chooseBuild(b.dataset.selectBuild));document.querySelectorAll('[data-building]').forEach(b=>b.onclick=()=>{selectedBuilding=Number(b.dataset.building);placement=null;render()});document.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>placeBuilding(b.dataset.cell));document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>action(b.dataset.act,b));document.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{selectedTarget=b.dataset.target;render()});document.querySelectorAll('[data-troop]').forEach(b=>b.onclick=()=>{selectedTroop=b.dataset.troop;render()});document.querySelectorAll('[data-rival]').forEach(b=>b.onclick=()=>action('start-raid',b));document.querySelectorAll('[data-edge]').forEach(b=>b.onclick=()=>action('deploy-edge',b))}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>showPage(b.dataset.page));
render();
})();

